/** Compare every configurable historical mixin with custom theme/config arguments. */
import {createHash} from 'node:crypto';
import {readFileSync,realpathSync} from 'node:fs';
import {dirname,isAbsolute,join,relative,resolve} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {SILENCE,THEME_PARAMS} from './sass-api-inventory.mjs';
import {measureSortPeer,sortCompanionResultsMatch,SORT_COMPANION_CASES} from './sass-sort-companion-contract.mjs';
import {measureTreePeer,treeCompanionResultsMatch,TREE_COMPANION_CASES} from './sass-tree-companion-contract.mjs';
import {measureCompanionAdditionPeer,companionAdditionResultsMatch,COMPANION_ADDITION_CASES} from './sass-companion-addition-contract.mjs';
import {measureProgressColorPeer,progressColorAliasResultsMatch,PROGRESS_COLOR_ALIAS_CASES} from './sass-progress-color-alias-contract.mjs';
import {measureBadgeShapePeer,badgeShapeResultsMatch,BADGE_SHAPE_CASES} from './sass-badge-shape-contract.mjs';
import {measureDatepickerControlsPeer,datepickerControlsResultsMatch,DATEPICKER_CONTROLS_CASES} from './sass-datepicker-controls-contract.mjs';
import {measureAggregateDensityPeers,aggregateDensityResultsMatch,AGGREGATE_DENSITY_CASES} from './sass-aggregate-density-contract.mjs';
import {measureAggregateTypographyPeer,aggregateTypographyResultsMatch,AGGREGATE_TYPOGRAPHY_CASES} from './sass-aggregate-typography-contract.mjs';
import {measureAggregateColorThemePeer,aggregateColorThemeResultsMatch,AGGREGATE_COLOR_THEME_CASES} from './sass-aggregate-color-theme-contract.mjs';
import {FORM_FIELD_STATE_ARGUMENT_CASES,FORM_FIELD_STATE_CONTRACT,measureFormFieldStatePeer,formFieldStateArgumentResultsMatch} from './sass-form-field-state-contract.mjs';
import {RIPPLE_COLOR_ARGUMENT_CASES,RIPPLE_COLOR_BINDING_CASES,RIPPLE_COLOR_CONTRACT,measureRippleColorPeer,rippleColorArgumentResultsMatch} from './sass-ripple-color-contract.mjs';
import {SPINNER_SNACK_GATE_CASES,spinnerSnackGateDescriptor,spinnerSnackGateDirectMatch,spinnerSnackGateAggregateMatch} from './sass-spinner-snack-gate-integration.mjs';
import {SPINNER_SNACK_BRIDGE_CASES,SPINNER_SNACK_BRIDGE_CONTRACT} from './sass-spinner-snack-bridge-contract.mjs';
import {SPINNER_SNACK_AGGREGATE_CASES} from './sass-spinner-snack-aggregate-contract.mjs';
import {ORDINARY_CONTROL_GATE_CASES,ORDINARY_CONTROL_DEFAULT_CASES,ORDINARY_CONTROL_CONTRACT,ordinaryControlGateDescriptor,ordinaryControlGateDirectMatch,ordinaryControlGateDefaultMatch} from './sass-ordinary-control-gate.mjs';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export const MIXIN_ARGUMENT_CATALOG='fixtures/sass/mixin-argument-contracts.json';
export function mixinArgumentCatalog() {
  const raw=readFileSync(join(root,MIXIN_ARGUMENT_CATALOG));const catalog=JSON.parse(raw);
  const oracle=JSON.parse(readFileSync(join(root,'compatibility/rc/oracles/material-16.2.14-sass-api.json')));
  const names=Object.entries(oracle.members.mixins).filter(([,entry])=>{
    const required=entry.params.filter(p=>p.default===null);
    return required.length>0 ? required.every(p=>THEME_PARAMS.includes(p.name))
      : entry.params.length===1 && THEME_PARAMS.includes(entry.params[0].name);
  }).map(([name])=>name).sort();
  const expected=[];
  for(const name of names) {
    const model=name.includes('legacy')?'legacy':'modern';const suffix=name.split('-').at(-1);
    let argument,variant;
    if(['color','colors'].includes(suffix)) {argument='m.get-color-config($'+model+'-light)';variant='raw-color-config';}
    else if(['typography','typographies','hierarchy'].includes(suffix)) {argument='$'+model;variant='raw-typography-config';}
    else if(['density','densities'].includes(suffix)) {argument='-2';variant='raw-density-config';}
    else if(['theme','themes'].includes(suffix)) {argument='$'+model+'-dark';variant='custom-dark-theme';}
    else throw new Error('unclassified configurable mixin '+name);
    for(const [mode,value] of [['custom-full-theme','$'+model+'-light'],[variant,argument]])
      expected.push({case_id:'mixin-argument/'+name+'/'+mode,mixin:name,variant:mode,argument:value,call:'.sass-argument-probe { @include m.'+name+'('+value+'); }'});
  }
  if(catalog.schema_version!==1 || names.length!==249 || typeof catalog.setup!=='string'
    || JSON.stringify(catalog.cases)!==JSON.stringify(expected)) throw new Error('configurable mixin argument roster is incomplete or changed');
  return {...catalog,sha256:sha(raw)};
}
export const mixinArgumentCaseIds=()=>mixinArgumentCatalog().cases.map(p=>p.case_id);
export function mixinArgumentProgram(catalog,probe) {return "@use '__entry__' as m;\n"+catalog.setup+'\n'+probe.call+'\n';}
export function measureMixinArgument(sass,entry,loadPaths,catalog,probe,allowedRoots,importers=[]) {
  const program=mixinArgumentProgram(catalog,probe);
  const measured=sass.compileString(program.replace("'__entry__'", "'"+pathToFileURL(entry).href+"'"),{
    loadPaths,importers,style:'expanded',silenceDeprecations:SILENCE,logger:{warn(){},debug(){}}});
  if(typeof measured.css!=='string')throw new Error('mixin probe returned no CSS');
  const sources=measured.loadedUrls.filter(url=>url.protocol==='file:').map(url=>{
    const path=realpathSync(fileURLToPath(url));
    const base=allowedRoots.find(base=>{const rel=relative(base,path);return rel==='' || (rel!=='..' && !rel.startsWith('../') && !isAbsolute(rel));});
    if(!base)throw new Error('mixin argument source outside authenticated roots: '+path);
    const bytes=readFileSync(path);return {root:allowedRoots.indexOf(base),path:relative(base,path).replaceAll('\\','/'),sha256:sha(bytes),bytes:bytes.length};
  }).sort((a,b)=>a.root-b.root || a.path.localeCompare(b.path));
  return {css:measured.css,css_sha256:sha(measured.css),css_bytes:Buffer.byteLength(measured.css),program_sha256:sha(program),sources};
}
// Diagnostic only: preserve complete CSS comparisons and report a bounded first mismatch.
export function firstMixinCssDifference(expected,actual) {
  if(typeof expected?.css!=='string' || typeof actual?.css!=='string' || expected.css===actual.css)return null;
  const a=expected.css,b=actual.css;let offset=0;
  while(offset<Math.min(a.length,b.length) && a[offset]===b[offset])offset++;
  const start=Math.max(0,offset-80),end=offset+240;
  return {utf16_offset:offset,reference_line:a.slice(0,offset).split('\n').length,
    expected_excerpt:a.slice(start,end),actual_excerpt:b.slice(start,end),
    expected_utf16_length:a.length,actual_utf16_length:b.length};
}
export function mixinArgumentResultsMatch(expected,actual) {
  return typeof expected?.css==='string' && typeof actual?.css==='string'
    && expected.css===actual.css && expected.css_sha256===sha(expected.css) && actual.css_sha256===sha(actual.css)
    && expected.css_bytes===Buffer.byteLength(expected.css) && actual.css_bytes===Buffer.byteLength(actual.css);
}
export function runMixinArgumentContracts({sass,entry,loadPaths,allowedRoots,importers=[],line,referenceEntry,referenceRoot,identity,spinnerSnackContext,ordinaryControlContext}) {
  const catalog=mixinArgumentCatalog();
  const provenance={...identity,catalog:MIXIN_ARGUMENT_CATALOG,catalog_sha256:catalog.sha256};
  const results=catalog.cases.map(probe=>{
    let expected,actual,error,current_companion,current_peer_alias,current_spinner_snack_bridge,current_ordinary_controls;
    try {
      expected=measureMixinArgument(sass,referenceEntry,[referenceRoot],catalog,probe,[referenceRoot]);
      actual=measureMixinArgument(sass,entry,loadPaths,catalog,probe,allowedRoots,importers);
      if(SPINNER_SNACK_GATE_CASES.includes(probe.case_id)){if(!spinnerSnackContext||spinnerSnackContext.line!==line)throw Error('spinner/snack current source context missing');current_spinner_snack_bridge=spinnerSnackGateDescriptor(spinnerSnackContext);}
      if(ORDINARY_CONTROL_GATE_CASES.includes(probe.case_id)){if(!ordinaryControlContext||ordinaryControlContext.line!==line)throw Error('ordinary controls current source context missing');current_ordinary_controls=ordinaryControlGateDescriptor(ordinaryControlContext);actual={...actual,line,sass_version:sass.info};}
      if(Object.hasOwn(RIPPLE_COLOR_BINDING_CASES,probe.case_id))actual={...actual,line,sass_version:sass.info};
      if (Object.hasOwn(RIPPLE_COLOR_ARGUMENT_CASES,probe.case_id)) {
        const peer=measureRippleColorPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:RIPPLE_COLOR_CONTRACT,peer};
      } else if (Object.hasOwn(FORM_FIELD_STATE_ARGUMENT_CASES,probe.case_id)) {
        const peer=measureFormFieldStatePeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:FORM_FIELD_STATE_CONTRACT,peer};
      } else if (Object.hasOwn(SORT_COMPANION_CASES,probe.case_id)) {
        const peer=measureSortPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'current-sort-color-with-original-fallback',peer};
      } else if (Object.hasOwn(TREE_COMPANION_CASES,probe.case_id)) {
        const peer=measureTreePeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'current-tree-dimensions-with-original-fallbacks',peer};
      } else if (Object.hasOwn(COMPANION_ADDITION_CASES,probe.case_id)) {
        const peer=measureCompanionAdditionPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'original-css-with-current-companion-addition',peer};
      } else if (Object.hasOwn(PROGRESS_COLOR_ALIAS_CASES,probe.case_id)) {
        const peer=measureProgressColorPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_peer_alias={classification:'conforming-current-infrastructure',contract:'historical-progress-css-with-public-color-aliases',peer};
      } else if (Object.hasOwn(BADGE_SHAPE_CASES,probe.case_id)) {
        const peer=measureBadgeShapePeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'historical-badge-shape-with-current-tokens',peer};
      } else if (Object.hasOwn(AGGREGATE_COLOR_THEME_CASES,probe.case_id)) {
        const peer=measureAggregateColorThemePeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'historical-color-theme-aggregate-with-qualified-members',peer};
      } else if (Object.hasOwn(AGGREGATE_TYPOGRAPHY_CASES,probe.case_id)) {
        const peer=measureAggregateTypographyPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'historical-typography-aggregate-with-qualified-members',peer};
      } else if (Object.hasOwn(AGGREGATE_DENSITY_CASES,probe.case_id)) {
        const peers=measureAggregateDensityPeers({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'historical-density-aggregate-with-qualified-tail',peers};
      } else if (Object.hasOwn(DATEPICKER_CONTROLS_CASES,probe.case_id)) {
        const peer=measureDatepickerControlsPeer({sass,materialRoot:allowedRoots[1],cdkRoot:allowedRoots[2],caseId:probe.case_id,line});
        current_companion={classification:'conforming-current-companion',contract:'historical-calendar-density-with-public-current-slots',peer};
      }
    }catch(caught){error=String(caught.message || caught);}
    const wrongCss=(actual?.css || '')+'\n.wrong-nonempty-mixin { color: red; }\n';
    const mutation={css:wrongCss,css_sha256:sha(wrongCss),css_bytes:Buffer.byteLength(wrongCss)};
    const conforms=value=>ORDINARY_CONTROL_GATE_CASES.includes(probe.case_id)
      ? ordinaryControlGateDirectMatch({context:ordinaryControlContext,caseId:probe.case_id,original:expected,actual:{...actual,...value},identity:provenance,descriptor:current_ordinary_controls,companion:current_companion??null})
      : SPINNER_SNACK_BRIDGE_CASES.includes(probe.case_id)
      ? spinnerSnackGateDirectMatch({context:spinnerSnackContext,caseId:probe.case_id,original:expected,actual:{...actual,...value},identity:provenance,descriptor:current_spinner_snack_bridge})
      : SPINNER_SNACK_AGGREGATE_CASES.includes(probe.case_id)
      ? spinnerSnackGateAggregateMatch({context:spinnerSnackContext,caseId:probe.case_id,original:expected,actual:{...actual,...value},companion:current_companion,descriptor:current_spinner_snack_bridge})
      : Object.hasOwn(RIPPLE_COLOR_ARGUMENT_CASES,probe.case_id)
      ? rippleColorArgumentResultsMatch(probe.case_id,expected,{...actual,...value},current_companion)
      : Object.hasOwn(FORM_FIELD_STATE_ARGUMENT_CASES,probe.case_id)
      ? formFieldStateArgumentResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(SORT_COMPANION_CASES,probe.case_id)
      ? sortCompanionResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(TREE_COMPANION_CASES,probe.case_id)
      ? treeCompanionResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(COMPANION_ADDITION_CASES,probe.case_id)
      ? companionAdditionResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(PROGRESS_COLOR_ALIAS_CASES,probe.case_id)
      ? progressColorAliasResultsMatch(probe.case_id,expected,value,current_peer_alias?.peer)
      : Object.hasOwn(BADGE_SHAPE_CASES,probe.case_id)
      ? badgeShapeResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(AGGREGATE_COLOR_THEME_CASES,probe.case_id)
      ? aggregateColorThemeResultsMatch(probe.case_id,expected,{...actual,...value},current_companion?.peer)
      : Object.hasOwn(AGGREGATE_TYPOGRAPHY_CASES,probe.case_id)
      ? aggregateTypographyResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : Object.hasOwn(AGGREGATE_DENSITY_CASES,probe.case_id)
      ? aggregateDensityResultsMatch(probe.case_id,expected,value,current_companion?.peers)
      : Object.hasOwn(DATEPICKER_CONTROLS_CASES,probe.case_id)
      ? datepickerControlsResultsMatch(probe.case_id,expected,value,current_companion?.peer)
      : mixinArgumentResultsMatch(expected,value);
    const mutation_rejected=Boolean(expected && actual && !conforms(mutation));
    const exact=mixinArgumentResultsMatch(expected,actual);
    return {...probe,line,expected,actual,error:error??null,identity:provenance,mutation,mutation_rejected,
      ...(current_companion?{current_companion}:{}),...(current_peer_alias?{current_peer_alias}:{}),...(current_spinner_snack_bridge?{current_spinner_snack_bridge}:{}),...(current_ordinary_controls?{current_ordinary_controls}:{}),
      comparison:ORDINARY_CONTROL_GATE_CASES.includes(probe.case_id)?ORDINARY_CONTROL_CONTRACT:SPINNER_SNACK_BRIDGE_CASES.includes(probe.case_id)?SPINNER_SNACK_BRIDGE_CONTRACT:current_companion?'current-companion-contract':current_peer_alias?'current-peer-color-alias-contract':exact?'historical-exact':'historical-mismatch',
      result:!error && conforms(actual) && mutation_rejected?'pass':'fail'};
  });
  return {results,identity:provenance,ok:results.length===498 && results.every(r=>r.result==='pass')};
}

#!/usr/bin/env node
/**
 * Sass API inventory of a module: exported variables (with inspected values),
 * functions and mixins (with declaration file and parsed signature), and the
 * ordered membership of all-* aggregate mixins.
 *
 * Members come from the compiler (meta.module-variables / -functions /
 * -mixins), not from a hand list. Declarations come from the compiler's own
 * "declaration" span on a deliberately invalid probe call, so forwards,
 * prefixes and show/hide lists are resolved by Sass itself.
 *
 *   node scripts/sass-api-inventory.mjs --reference <node_modules> --out <json>
 *
 * The --reference mode generates the frozen Material 16.2.14 oracle from the
 * authentic isolated reference environment (reference/material-16.2.14/
 * environment-package*.json). sass-seal.mjs imports the same functions for the
 * packed candidate.
 */
import {createHash} from 'node:crypto';
import {readFileSync, writeFileSync, existsSync} from 'node:fs';
import {createRequire} from 'node:module';
import {dirname, join, relative, resolve, isAbsolute} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';

import {DEFAULT_CORE_CDK_CASES,defaultCoreCdkResultsMatch,defaultCoreCdkMeasurementOk,DEFAULT_CORE_CDK_CONTRACT} from './sass-default-core-cdk-contract.mjs';
import {DEFAULT_COMPANION_CASES,DEFAULT_COMPANION_CONTRACT,defaultCompanionMeasurementOk,defaultCompanionResultsMatch} from './sass-default-companion-contract.mjs';
import {DEFAULT_MAPPED_COMPANION_CASES,DEFAULT_MAPPED_COMPANION_CONTRACT,defaultMappedCompanionMeasurementOk,defaultMappedCompanionResultsMatch} from './sass-default-mapped-companion-contract.mjs';
import {DEFAULT_AGGREGATE_CASES,DEFAULT_AGGREGATE_CONTRACT,defaultAggregateMeasurementOk,defaultAggregateResultsMatch} from './sass-default-aggregate-contract.mjs';
import {FORM_FIELD_STATE_DEFAULT_CASES,FORM_FIELD_STATE_CONTRACT,formFieldStateDefaultMeasurementOk,formFieldStateDefaultResultsMatch} from './sass-form-field-state-contract.mjs';
import {RIPPLE_COLOR_DEFAULT_CASES,RIPPLE_COLOR_CONTRACT,rippleColorMeasurementOkay,rippleColorDefaultResultsMatch} from './sass-ripple-color-contract.mjs';
import {SPINNER_SNACK_DEFAULT_CASES,spinnerSnackGateDefaultMatch,spinnerSnackGateAggregateMatch} from './sass-spinner-snack-gate-integration.mjs';
import {SPINNER_SNACK_AGGREGATE_CASES} from './sass-spinner-snack-aggregate-contract.mjs';
import {ORDINARY_CONTROL_GATE_CASES,ORDINARY_CONTROL_DEFAULT_CASES,ORDINARY_CONTROL_CONTRACT,ordinaryControlGateDescriptor,ordinaryControlGateDirectMatch,ordinaryControlGateDefaultMatch} from './sass-ordinary-control-gate.mjs';
const companionTypes=[
  {cases:RIPPLE_COLOR_DEFAULT_CASES,contract:RIPPLE_COLOR_CONTRACT,measurement:rippleColorMeasurementOkay,matches:rippleColorDefaultResultsMatch},
  {cases:FORM_FIELD_STATE_DEFAULT_CASES,contract:FORM_FIELD_STATE_CONTRACT,measurement:formFieldStateDefaultMeasurementOk,matches:formFieldStateDefaultResultsMatch},
  {cases:DEFAULT_COMPANION_CASES,contract:DEFAULT_COMPANION_CONTRACT,measurement:defaultCompanionMeasurementOk,matches:defaultCompanionResultsMatch},
  {cases:DEFAULT_MAPPED_COMPANION_CASES,contract:DEFAULT_MAPPED_COMPANION_CONTRACT,measurement:defaultMappedCompanionMeasurementOk,matches:defaultMappedCompanionResultsMatch},
  {cases:DEFAULT_AGGREGATE_CASES,contract:DEFAULT_AGGREGATE_CONTRACT,measurement:defaultAggregateMeasurementOk,matches:defaultAggregateResultsMatch},
];
function companionType(id){return companionTypes.find(t=>Object.hasOwn(t.cases,id));}
function companionFailure(id,got,spinnerSnackContext){
  if(SPINNER_SNACK_AGGREGATE_CASES.includes(id))return spinnerSnackContext&&got.css===got.actual_measurement?.css&&got.sha256===got.actual_measurement?.css_sha256&&spinnerSnackGateAggregateMatch({context:spinnerSnackContext,caseId:id,actual:got.actual_measurement,companion:got.current_companion,descriptor:got.current_spinner_snack_bridge})?null:'finite spinner/snack aggregate contract differs';
  const type=companionType(id);
  return !type||!type.measurement(id,got.actual_measurement,got.actual_measurement?.line)||!type.matches(id,got,got.current_companion)
    ? 'finite default companion contract differs':null;
}
const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const SILENCE = ['import', 'if-function', 'global-builtin', 'color-functions', 'mixed-decls', 'slash-div'];
const QUIET = {warn() {}, debug() {}};

function sha256(text) {
  return createHash('sha256').update(text).digest('hex');
}

/** Split a Sass list/arg string at top-level commas. */
export function splitTopLevel(text) {
  const parts = [];
  let depth = 0;
  let quote = null;
  let current = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (quote) {
      current += ch;
      if (ch === quote && text[i - 1] !== '\\') quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") { quote = ch; current += ch; continue; }
    if (ch === '(' || ch === '[') depth += 1;
    if (ch === ')' || ch === ']') depth -= 1;
    if (ch === ',' && depth === 0) { parts.push(current); current = ''; continue; }
    current += ch;
  }
  if (current.trim()) parts.push(current);
  return parts.map(part => part.trim()).filter(Boolean);
}

function stripComments(text) {
  return text.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:\\])\/\/[^\n]*/g, '$1');
}

/** Parse a parameter list: [{name, default}] plus rest. Defaults are whitespace-normalized source text. */
export function parseParams(paramText) {
  const params = [];
  let rest = null;
  for (const raw of splitTopLevel(stripComments(paramText))) {
    const item = raw.replace(/\s+/g, ' ').trim();
    const restMatch = item.match(/^\$([\w-]+)\.\.\.$/);
    if (restMatch) { rest = restMatch[1].replace(/_/g, '-'); continue; }
    const match = item.match(/^\$([\w-]+)\s*(?::\s*([\s\S]+))?$/);
    if (!match) throw new Error(`unparsed parameter: ${item}`);
    params.push({name: match[1].replace(/_/g, '-'), default: match[2] === undefined ? null : match[2].trim()});
  }
  return {params, rest};
}

/** Text of the declaration (params and body) of `@mixin|@function name` starting near line. */
export function declarationAt(text, kind, name, line) {
  const lines = text.split('\n');
  const start = lines.slice(0, Math.max(0, line - 1)).join('\n').length;
  const re = new RegExp(`@${kind}\\s+${name.replace(/[-_]/g, '[-_]')}\\s*(\\(|\\{)`, 'g');
  re.lastIndex = Math.max(0, start - 1);
  const match = re.exec(text);
  if (!match) return null;
  let i = match.index + match[0].length - 1;
  let paramText = '';
  if (text[i] === '(') {
    let depth = 0;
    const open = i;
    for (; i < text.length; i += 1) {
      if (text[i] === '(') depth += 1;
      else if (text[i] === ')') { depth -= 1; if (depth === 0) break; }
    }
    paramText = text.slice(open + 1, i);
    i = text.indexOf('{', i);
  }
  let depth = 0;
  const bodyStart = i;
  for (; i < text.length; i += 1) {
    if (text[i] === '{') depth += 1;
    else if (text[i] === '}') { depth -= 1; if (depth === 0) break; }
  }
  return {paramText, body: text.slice(bodyStart + 1, i)};
}

function loadSass(sassModule) {
  return sassModule || createRequire(join(root, 'package.json'))('sass');
}

/** Exported member names of a module, from the compiler. */
export function enumerateModule(sass, moduleUrl, loadPaths, importers = []) {
  const out = {};
  const source = `@use 'sass:meta'; @use 'sass:map'; @use '${moduleUrl}' as m;
@debug "VARS" meta.inspect(map.keys(meta.module-variables(m)));
@debug "FUNCS" meta.inspect(map.keys(meta.module-functions(m)));
@debug "MIXINS" meta.inspect(map.keys(meta.module-mixins(m)));`;
  sass.compileString(source, {
    loadPaths, importers, silenceDeprecations: SILENCE,
    logger: {warn() {}, debug(message) {
      const [key, ...restParts] = message.split(' ');
      const list = restParts.join(' ').replace(/^\(|\)$/g, '');
      out[key.replace(/"/g, '')] = list ? list.split(', ').map(item => item.replace(/^"|"$/g, '')) : [];
    }},
  });
  return {variables: out.VARS.sort(), functions: out.FUNCS.sort(), mixins: out.MIXINS.sort()};
}

/** Inspected value of every exported variable. */
export function variableValues(sass, moduleUrl, loadPaths, names, importers = []) {
  const values = {};
  const body = names.map(name => `@debug "${name}=" + meta.inspect(m.$${name});`).join('\n');
  sass.compileString(`@use 'sass:meta'; @use '${moduleUrl}' as m;\n${body}`, {
    loadPaths, importers, silenceDeprecations: SILENCE,
    logger: {warn() {}, debug(message) {
      const at = message.indexOf('=');
      values[message.slice(0, at)] = message.slice(at + 1);
    }},
  });
  return values;
}

const DECLARATION = /┌──> ([^\n]+)\n\s*(\d+)\s*│[^\n]*\n[\s\S]*?declaration/;

/** Declaration file/line of an exported member, from the compiler's own error span. */
export function locateMember(sass, moduleUrl, loadPaths, kind, name, importers = []) {
  const call = kind === 'mixin'
    ? `@include m.${name}($__inventory-probe__: null);`
    : `a { b: meta.inspect(m.${name}($__inventory-probe__: null)); }`;
  try {
    sass.compileString(`@use 'sass:meta'; @use '${moduleUrl}' as m;\n${call}`, {
      loadPaths, importers, silenceDeprecations: SILENCE, logger: QUIET,
    });
  } catch (error) {
    const match = String(error.message).match(DECLARATION);
    if (match) return {file: match[1].trim(), line: Number(match[2]), probe_error: error.sassMessage};
    return {file: null, line: null, probe_error: error.sassMessage ?? String(error.message).split('\n')[0]};
  }
  return {file: null, line: null, probe_error: null};
}

function resolveFile(file, loadPaths) {
  if (isAbsolute(file) && existsSync(file)) return file;
  for (const base of [process.cwd(), ...loadPaths, ...loadPaths.map(dirname)]) {
    const candidate = resolve(base, file);
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

/** Strip a package root and the leading underscore / extension for a stable path id. */
export function packagePathId(absolute, packageRoot) {
  const rel = relative(packageRoot, absolute).split('\\').join('/');
  return rel.replace(/(^|\/)_([^/]+)$/, '$1$2').replace(/\.scss$/, '');
}

/** Ordered @include targets of an aggregate body, as `<used module path id>#<mixin>`. */
export function aggregateMembers(body, fileText) {
  const uses = new Map();
  for (const match of stripComments(fileText).matchAll(/@use\s+['"]([^'"]+)['"](?:\s+as\s+([\w-]+))?/g)) {
    const path = match[1];
    const ns = match[2] || path.split('/').pop().replace(/^_/, '').replace(/\.scss$/, '');
    uses.set(ns, path);
  }
  const members = [];
  for (const match of stripComments(body).matchAll(/@include\s+(?:([\w-]+)\.)?([\w-]+)/g)) {
    const [, ns, mixin] = match;
    const path = ns ? uses.get(ns) ?? `?${ns}` : '.';
    members.push(`${path.split('/').slice(-2).join('/').replace(/(^|\/)_/, '$1')}#${mixin}`);
  }
  return members;
}

/** Full inventory of a module. */
export function inventoryModule({sass: sassModule, moduleUrl, loadPaths, packageRoot, importers = []}) {
  const sass = loadSass(sassModule);
  const names = enumerateModule(sass, moduleUrl, loadPaths, importers);
  const values = variableValues(sass, moduleUrl, loadPaths, names.variables, importers);
  const members = {variables: {}, functions: {}, mixins: {}};
  for (const name of names.variables) members.variables[name] = {value: values[name] ?? null};
  for (const [kind, key] of [['function', 'functions'], ['mixin', 'mixins']]) {
    for (const name of names[key]) {
      const located = locateMember(sass, moduleUrl, loadPaths, kind, name, importers);
      const entry = {file: null, params: null, rest: null, probe_error: located.probe_error};
      const file = located.file ? resolveFile(located.file, loadPaths) : null;
      if (file) {
        const text = readFileSync(file, 'utf8');
        const base = name.replace(/^.*?([\w-]+)$/, '$1');
        let declaration = null;
        // A prefixed forward exposes `prefix-base`; try the longest suffix that is declared at that line.
        const parts = base.split('-');
        for (let i = 0; i < parts.length && !declaration; i += 1) {
          declaration = declarationAt(text, kind, parts.slice(i).join('-'), located.line);
        }
        if (declaration) {
          const parsed = parseParams(declaration.paramText);
          entry.file = packagePathId(file, packageRoot);
          entry.line = located.line;
          entry.params = parsed.params;
          entry.rest = parsed.rest;
          entry.content = /@content\b/.test(stripComments(declaration.body));
          if (kind === 'mixin' && /^all-/.test(name)) entry.aggregate = aggregateMembers(declaration.body, text);
        }
      }
      members[key][name] = entry;
    }
  }
  return members;
}

function main(argv) {
  let reference = null;
  let out = null;
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--reference') reference = resolve(argv[++i]);
    else if (argv[i] === '--out') out = resolve(argv[++i]);
    else throw new Error(`unknown argument ${argv[i]}`);
  }
  if (!reference || !out) throw new Error('--reference <node_modules> and --out <json> are required');
  const sass = createRequire(join(reference, 'sass', 'package.json'))('sass');
  const materialRoot = join(reference, '@angular/material');
  const pkg = JSON.parse(readFileSync(join(materialRoot, 'package.json'), 'utf8'));
  if (pkg.version !== '16.2.14') throw new Error(`reference @angular/material is ${pkg.version}, not 16.2.14`);
  const lockPath = join(root, 'reference/material-16.2.14/environment-package-lock.json');
  const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
  const members = inventoryModule({sass, moduleUrl: '@angular/material', loadPaths: [reference], packageRoot: materialRoot});
  for (const [name, entry] of Object.entries(members.mixins)) {
    const plan = invocationPlan(name, entry);
    entry.invocation = {invocable: plan.invocable, reason: plan.reason};
    if (plan.argument_source) entry.invocation.argument_source = plan.argument_source;
    if (!plan.invocable) continue;
    const compiled = compileInvocation(sass, '@angular/material', [reference], plan.call);
    if (compiled.error) throw new Error(`reference invocation of ${name} failed: ${compiled.error}`);
    entry.invocation.css_sha256 = sha256(compiled.css);
    entry.invocation.css_bytes = Buffer.byteLength(compiled.css);
  }
  const report = {
    schema_version: 1,
    role: 'authentic @angular/material 16.2.14 Sass API inventory',
    provenance: {
      package: '@angular/material',
      version: pkg.version,
      lock_path: 'reference/material-16.2.14/environment-package-lock.json',
      lock_sha256: sha256(readFileSync(lockPath)),
      material_integrity: lock.packages['node_modules/@angular/material']?.integrity ?? null,
      cdk_integrity: lock.packages['node_modules/@angular/cdk']?.integrity ?? null,
      index_sha256: sha256(readFileSync(join(materialRoot, '_index.scss'))),
      sass_version: JSON.parse(readFileSync(join(reference, 'sass/package.json'), 'utf8')).version,
      generator: 'scripts/sass-api-inventory.mjs --reference',
      argument_cases_sha256: existsSync(ARGUMENT_CASES_PATH) ? sha256(readFileSync(ARGUMENT_CASES_PATH)) : null,
    },
    counts: Object.fromEntries(Object.entries(members).map(([key, value]) => [key, Object.keys(value).length])),
    standard_theme: standardThemeSource(),
    members,
  };
  writeFileSync(out, `${JSON.stringify(report, null, 1)}\n`);
  console.log(JSON.stringify(report.counts));
}


/** Required parameters that the predeclared standard theme satisfies. Nothing else is guessed. */
export const THEME_PARAMS = Object.freeze([
  'config-or-theme',
  'theme-or-color-config',
  'config-or-theme-or-color',
  'theme-or-color-config-or-color',
]);

/** The one predeclared theme every invocable mixin receives, built by the module's own constructors. */
export function standardThemeSource() {
  return `$__theme: m.define-light-theme((
  color: (
    primary: m.define-palette(m.$indigo-palette),
    accent: m.define-palette(m.$pink-palette, A200, A100, A400),
    warn: m.define-palette(m.$red-palette),
  ),
  typography: m.define-typography-config(),
  density: 0,
));`;
}

export const ARGUMENT_CASES_PATH = join(root, 'compatibility/rc/oracles/material-16.2.14-sass-argument-cases.json');
let argumentCasesCache = null;

/** Authentic 16.2.14 argument cases, transcribed from cited callers, docs and tests. */
export function argumentCases() {
  if (argumentCasesCache === null) {
    argumentCasesCache = existsSync(ARGUMENT_CASES_PATH)
      ? JSON.parse(readFileSync(ARGUMENT_CASES_PATH, 'utf8')).mixins || {}
      : {};
  }
  return argumentCasesCache;
}

/** Invocation plan for a mixin entry: {invocable, reason, call, argument_source}. */
export function invocationPlan(name, entry, cases = argumentCases()) {
  if (!entry || !Array.isArray(entry.params)) return {invocable: false, reason: 'signature unknown', call: null};
  const required = entry.params.filter(param => param.default === null).map(param => param.name);
  const unknown = required.filter(param => !THEME_PARAMS.includes(param));
  if (unknown.length) {
    const authentic = Object.prototype.hasOwnProperty.call(cases, name) ? cases[name] : null;
    if (authentic && typeof authentic.call === 'string' && Array.isArray(authentic.sources) && authentic.sources.length) {
      // Top level exactly as the cited caller wrote it; identical on both sides.
      return {invocable: true, reason: null, call: authentic.call, argument_source: authentic.sources};
    }
    return {invocable: false, reason: `required parameters without a predeclared argument: ${unknown.map(p => `$${p}`).join(', ')}`, call: null};
  }
  const args = required.map(() => '$__theme').join(', ');
  // Every invocation sits in the same probe rule so declaration-only mixins compile;
  // both sides receive the identical wrapper.
  return {invocable: true, reason: null, call: `.sass-api-probe { @include m.${name}(${args}); }`};
}

/** Compile one planned invocation; returns {css, error, loaded}. */
export function compileInvocation(sass, moduleUrl, loadPaths, call, {importers = []} = {}) {
  const source = `@use '${moduleUrl}' as m;\n${standardThemeSource()}\n${call}\n`;
  try {
    const result = sass.compileString(source, {
      loadPaths, importers, style: 'expanded', silenceDeprecations: SILENCE, logger: QUIET,
    });
    return {css: result.css, error: null, loaded: result.loadedUrls.map(url => url.href)};
  } catch (error) {
    return {css: null, error: error.sassMessage ?? String(error.message).split('\n')[0], loaded: []};
  }
}

/** Predeclared sass-api-and-values case ids, derived only from the authentic oracle. */
export function apiCaseIds(oracle) {
  const members = oracle.members;
  const ids = [];
  for (const name of Object.keys(members.variables).sort()) ids.push(`variable/${name}`);
  for (const name of Object.keys(members.functions).sort()) ids.push(`function/${name}`);
  for (const name of Object.keys(members.mixins).sort()) ids.push(`mixin/${name}`);
  for (const name of Object.keys(members.mixins).sort()) ids.push(`mixin-css/${name}`);
  for (const name of Object.keys(members.mixins).sort()) {
    if (Array.isArray(members.mixins[name].aggregate)) ids.push(`aggregate/${name}`);
  }
  return ids;
}

function sameSignature(expected, actual) {
  if (!actual || !Array.isArray(actual.params)) return 'candidate signature unknown';
  if (JSON.stringify(expected.params) !== JSON.stringify(actual.params)) {
    return `parameters differ: expected (${expected.params.map(fmtParam).join(', ')}) got (${actual.params.map(fmtParam).join(', ')})`;
  }
  if ((expected.rest ?? null) !== (actual.rest ?? null)) return `rest parameter differs: ${expected.rest} vs ${actual.rest}`;
  if (expected.content !== undefined && Boolean(expected.content) !== Boolean(actual.content)) {
    return `@content acceptance differs: ${expected.content} vs ${actual.content}`;
  }
  return null;
}

function fmtParam(param) {
  return param.default === null ? `$${param.name}` : `$${param.name}: ${param.default}`;
}

/**
 * Pure comparison of a candidate inventory (and its invocation CSS digests)
 * against the oracle. One result per predeclared case id; nothing is dropped.
 */
export function compareInventory(oracle, candidate, candidateCss,{spinnerSnackContext,ordinaryControlContext}={}) {
  const results = [];
  const push = (case_id, failure, extra = {}) => results.push({case_id, result: failure ? 'fail' : 'pass', reason: failure, ...extra});
  const om = oracle.members;
  const cm = candidate || {variables: {}, functions: {}, mixins: {}};
  for (const name of Object.keys(om.variables).sort()) {
    const expected = om.variables[name].value;
    const actual = cm.variables?.[name]?.value;
    push(`variable/${name}`, actual === undefined ? 'missing from candidate'
      : actual !== expected ? 'value differs' : null, {expected, actual: actual ?? null});
  }
  for (const [kind, key] of [['function', 'functions'], ['mixin', 'mixins']]) {
    for (const name of Object.keys(om[key]).sort()) {
      const actual = cm[key]?.[name];
      push(`${kind}/${name}`, actual ? sameSignature(om[key][name], actual) : 'missing from candidate', {
        expected_params: om[key][name].params, actual_params: actual?.params ?? null,
      });
    }
  }
  for (const name of Object.keys(om.mixins).sort()) {
    const invocation = om.mixins[name].invocation || {};
    if (!invocation.invocable) {
      push(`mixin-css/${name}`, `not invoked: ${invocation.reason}`, {invocable: false});
      continue;
    }
    const got = candidateCss?.[name];
    const failure = !got ? 'candidate invocation missing'
      : got.error ? `candidate invocation failed: ${got.error}`
        : ORDINARY_CONTROL_DEFAULT_CASES.includes(`mixin-css/${name}`)
          ? (ordinaryControlContext&&ordinaryControlGateDefaultMatch({context:ordinaryControlContext,caseId:`mixin-css/${name}`,got})?null:'finite ordinary controls default contract differs')
        : Object.hasOwn(got,'current_ordinary_controls') ? 'ordinary controls capsule outside finite scope'
        : SPINNER_SNACK_DEFAULT_CASES.includes(`mixin-css/${name}`)
          ? (spinnerSnackContext&&spinnerSnackGateDefaultMatch({context:spinnerSnackContext,caseId:`mixin-css/${name}`,got})?null:'finite spinner/snack default contract differs')
        : Object.hasOwn(got,'current_companion')&&Object.hasOwn(got,'current_infrastructure') ? 'conflicting default contracts'
        : Object.hasOwn(got,'current_infrastructure')
          ? (!Object.hasOwn(DEFAULT_CORE_CDK_CASES,`mixin-css/${name}`)
            || !defaultCoreCdkMeasurementOk(`mixin-css/${name}`,got.actual_measurement,got.actual_measurement?.line)
            || !defaultCoreCdkResultsMatch(`mixin-css/${name}`,got,got.current_infrastructure) ? 'finite current CDK contract differs' : null)
          : Object.hasOwn(got,'current_companion')
            ? companionFailure(`mixin-css/${name}`,got,spinnerSnackContext)
            : got.sha256 !== invocation.css_sha256 ? 'compiled CSS differs' : null;
    push(`mixin-css/${name}`, failure, {
      invocable: true, expected_sha256: invocation.css_sha256, expected_bytes: invocation.css_bytes,
      actual_sha256: got?.sha256 ?? null, actual_bytes: got?.css === undefined ? null : Buffer.byteLength(got.css),
      ...(got&&ORDINARY_CONTROL_DEFAULT_CASES.includes(`mixin-css/${name}`)?{current_ordinary_controls:got.current_ordinary_controls,error:got.error??null,actual_measurement:got.actual_measurement,expected:got.expected,actual:got.actual_measurement,identity:got.identity,mixin:got.mixin,variant:got.variant,call:got.call,comparison:got.comparison,mutation:got.mutation,mutation_rejected:got.mutation_rejected}:{}),
      ...(got&&Object.hasOwn(got,'current_spinner_snack_bridge')?{current_spinner_snack_bridge:got.current_spinner_snack_bridge,error:null,actual_measurement:got.actual_measurement}:{}),
      ...(got&&SPINNER_SNACK_DEFAULT_CASES.includes(`mixin-css/${name}`)?{expected:got.expected,actual:got.actual_measurement,identity:got.identity,mixin:got.mixin,variant:got.variant,call:got.call,comparison:got.comparison,mutation:got.mutation,mutation_rejected:got.mutation_rejected}:{}),
      ...(got&&Object.hasOwn(got,'current_infrastructure')?{current_infrastructure:got.current_infrastructure,actual_measurement:got.actual_measurement,comparison:DEFAULT_CORE_CDK_CONTRACT}:{}),
      ...(got&&Object.hasOwn(got,'current_companion')?{current_companion:got.current_companion,actual_measurement:got.actual_measurement,comparison:ORDINARY_CONTROL_DEFAULT_CASES.includes(`mixin-css/${name}`)?got.comparison:companionType(`mixin-css/${name}`)?.contract??DEFAULT_COMPANION_CONTRACT}:{}),
    });
  }
  for (const name of Object.keys(om.mixins).sort()) {
    const expected = om.mixins[name].aggregate;
    if (!Array.isArray(expected)) continue;
    const actual = cm.mixins?.[name]?.aggregate ?? null;
    push(`aggregate/${name}`, !Array.isArray(actual) ? 'candidate aggregate membership unknown'
      : JSON.stringify(actual) !== JSON.stringify(expected) ? 'membership or order differs' : null, {expected, actual});
  }
  return results;
}

/**
 * Mark a failing case as pending only when a recorded pending decision names
 * that case with the exact expected and candidate sha256. Pending never passes.
 */
export function classifyPending(results, decisions) {
  const index = new Map();
  for (const decision of decisions?.decisions || []) {
    if (decision?.state !== 'pending') continue;
    for (const item of decision.cases || []) index.set(item.case_id, {decision: decision.id, item});
  }
  return results.map(result => {
    if (result.result === 'pass') return result;
    const hit = index.get(result.case_id);
    if (!hit) return {...result, status: 'unexplained-failure'};
    const {item} = hit;
    const exact = item.expected_sha256 === undefined
      ? result.invocable === false && typeof item.reason === 'string' && result.reason === `not invoked: ${item.reason}`
      : item.expected_sha256 === result.expected_sha256 && item.candidate_sha256 === result.actual_sha256;
    return exact
      ? {...result, status: 'pending-decision', decision: hit.decision}
      : {...result, status: 'unexplained-failure', stale_decision: hit.decision};
  });
}

/**
 * API negative: wrong-but-nonempty mutations of a candidate inventory must
 * fail exactly their own cases. Returns {detected, expected, failed}.
 */
export function apiDriftNegative(oracle, candidate, candidateCss,options={}) {
  const copy = JSON.parse(JSON.stringify(candidate));
  const css = JSON.parse(JSON.stringify(candidateCss || {}));
  const mutated = [];
  const variable = Object.keys(oracle.members.variables).sort()[0];
  if (copy.variables[variable]) { copy.variables[variable].value = `${copy.variables[variable].value} `; mutated.push(`variable/${variable}`); }
  const fn = Object.keys(oracle.members.functions).sort().find(name => oracle.members.functions[name].params?.some(p => p.default !== null));
  if (fn && copy.functions[fn]?.params) {
    const param = copy.functions[fn].params.find(p => p.default !== null);
    param.default = `${param.default}-drift`;
    mutated.push(`function/${fn}`);
  }
  const removed = Object.keys(oracle.members.mixins).sort().find(name => !/^all-/.test(name));
  delete copy.mixins[removed];
  mutated.push(`mixin/${removed}`);
  const cssName = Object.keys(oracle.members.mixins).sort().find(name => oracle.members.mixins[name].invocation?.invocable && css[name]?.sha256);
  if (cssName) { css[cssName] = {...css[cssName], sha256: '0'.repeat(64)}; mutated.push(`mixin-css/${cssName}`); }
  const baseline = new Set(compareInventory(oracle, candidate, candidateCss,options).filter(r => r.result === 'fail').map(r => r.case_id));
  const after = new Set(compareInventory(oracle, copy, css,options).filter(r => r.result === 'fail').map(r => r.case_id));
  const newly = [...after].filter(id => !baseline.has(id)).sort();
  const expectedNew = mutated.filter(id => !baseline.has(id)).sort();
  return {detected: expectedNew.length > 0 && JSON.stringify(newly) === JSON.stringify(expectedNew), mutated, newly_failed: newly};
}

const entry = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : '';
if (import.meta.url === entry) main(process.argv.slice(2));

/** Complete finite Sass results; a digest-matched pending decision is a failure. */
export function sassResultsComplete(results,expectedIds) {
  if (!Array.isArray(results) || !Array.isArray(expectedIds) || !expectedIds.length || results.length !== expectedIds.length) return false;
  const expected = new Set(expectedIds), seen = new Set();
  if (expected.size !== expectedIds.length) return false;
  return results.every(item => {
    if (!item || item.result !== 'pass' || ['pending-decision','unexplained-failure'].includes(item.status) || !expected.has(item.case_id) || seen.has(item.case_id)) return false;
    seen.add(item.case_id);return true;
  });
}

#!/usr/bin/env node
/**
 * Peer-aware Sass seal against a packed library artifact (full-verify sass-seal).
 *
 * Installs the identified tarball plus exact public peers in an isolated
 * consumer, compiles the packed facade allowing only declared @angular/material
 * (and @angular/cdk) public Sass, rejects archived @material/* and undeclared
 * workspace loads, runs the three sealed value fixtures, compares the finite
 * exact ordered-CSS fixtures, and proves a forbidden-import negative.
 *
 * sass-api-and-values: the predeclared case set comes from the frozen authentic
 * Material 16.2.14 inventory (compatibility/rc/oracles/material-16.2.14-sass-api.json,
 * scripts/sass-api-inventory.mjs): every exported variable value, function and
 * mixin signature, the CSS of every mixin invoked with the one predeclared
 * theme, and all-* aggregate membership/order. The ordered-CSS roster is every
 * non-debug fixture of fixtures/sass/manifest.json against the unmodified
 * sealed CSS. A failing case whose exact expected/candidate digests are named
 * by a pending decision (compatibility/rc/sass-pending-decisions.json) is
 * reported as pending; it never passes and writes no assertion. Isolation
 * negatives: archived @material/button rejection, a mutated sealed CSS copy,
 * a hidden load-path resolution, and API drift. It does not cover DOM or
 * main on this branch, and pending decisions never pass.
 *
 *   node scripts/sass-seal.mjs --tarball <path>
 *   node scripts/sass-seal.mjs --run <run.json>
 *
 * Does not claim G06–G08.
 */
