def _contract_artifacts(row: dict) -> dict | None:
    subjects = row["acceptance"]["subject_ids"]
    if not isinstance(subjects, list) or not subjects:
        return None
    wanted = [aid for aid in subjects if aid != "source"]
    by_id: dict = {}
    for item in ACTIVE_RUN.manifest.get("artifacts", []):
        aid = item.get("id")
        if aid not in wanted:
            continue
        if aid in by_id:
            return None
        digest = item.get("sha256")
        size = item.get("bytes")
        if not isinstance(digest, str) or type(size) is not int or size <= 0:
            return None
        by_id[aid] = {"sha256": digest, "bytes": size}
    if set(by_id) != set(wanted):
        return None
    return {aid: by_id[aid] for aid in wanted}


def _roster_assertion_records(run_dir: Path, check_id: str, invocation: str, expected: list[str]) -> dict | None:
    prefix = assertion_directory(check_id, invocation)
    directory = run_dir / prefix
    if not directory.is_dir() or directory.is_symlink():
        return None
    reserved = _reserved_evidence(run_dir)
    allowed = set(expected)
    found: dict = {}
    for path in sorted(directory.iterdir()):
        if not path.is_file() or path.is_symlink() or path.stat().st_nlink != 1:
            continue
        if path.name in _MIGRATION_RESERVED_NAMES or path.suffix != ".json":
            continue
        if path.name.endswith((".sha256", ".sha512", ".sha1")):
            continue
        identity = (evidence_sha256(path), path.stat().st_size)
        if identity in reserved:
            continue
        try:
            body = read_json(path)
        except EvidenceError:
            continue
        case_id = body.get("case_id")
        if body.get("result") != "pass" or body.get("kind") != "assertion":
            continue
        if not isinstance(case_id, str) or case_id not in allowed or case_id in found:
            if isinstance(case_id, str) and case_id in found:
                return None
            continue
        body_check = _ASSERTION_BODY_CHECKS.get(check_id)
        if body_check is not None and not body_check(body, invocation):
            continue
        relative = path.relative_to(run_dir).as_posix()
        if not relative.startswith(prefix + "/"):
            continue
        found[case_id] = {"path": relative, "sha256": identity[0], "bytes": identity[1]}
    if set(found) != allowed:
        return None
    return found


_PEER_SOURCE_FILE = re.compile(r"^([a-z0-9-]+)/_m2-\1\.scss$")


def _current_peer_version(package: str) -> str | None:
    for item in (ACTIVE_RUN.manifest.get("oracles") or {}).get("current_peer") or []:
        if isinstance(item, dict) and item.get("id") == package:
            version = item.get("version")
            return version if isinstance(version, str) and version else None
    return None


def _bridge_token_assertion_ok(body: dict, invocation: str) -> bool:
    case_id = body.get("case_id")
    component = body.get("component")
    key = body.get("allowed_key")
    if not all(isinstance(v, str) and v for v in (case_id, component, key)):
        return False
    if body.get("token") != case_id or case_id != f"--mat-{component}-{key}":
        return False
    if body.get("run_id") != ACTIVE_RUN.manifest.get("run_id") or body.get("invocation_id") != invocation:
        return False
    if body.get("peer_package") != "@angular/material":
        return False
    peer_version = _current_peer_version("@angular/material")
    if peer_version is None or body.get("peer_version") != peer_version:
        return False
    source = body.get("peer_source_file")
    match = _PEER_SOURCE_FILE.fullmatch(source) if isinstance(source, str) else None
    if match is None or match.group(1) != component:
        return False
    if not (isinstance(body.get("peer_source_sha256"), str) and re.fullmatch(r"[0-9a-f]{64}", body["peer_source_sha256"])):
        return False
    expected, candidate = body.get("expected_peer"), body.get("candidate")
    if not (isinstance(expected, str) and expected and candidate == expected):
        return False
    scenarios = body.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        return False
    for scenario in scenarios:
        checks = scenario.get("selector_checks") if isinstance(scenario, dict) else None
        if scenario.get("match") is not True or not isinstance(checks, list) or not checks:
            return False
        for check in checks:
            if not isinstance(check, dict) or check.get("match") is not True:
                return False
            value = check.get("expected_peer")
            if not (isinstance(value, str) and value and check.get("candidate") == value):
                return False
    return True


_CSS_WIDE_KEYWORDS = ("inherit", "initial", "unset", "revert", "revert-layer")

_COMPUTED_FOREIGN_TOKEN_PREFIXES = {("datepicker", "density"): ("--mat-icon-button-",)}

_COMPUTED_DIMENSIONS = ("base", "color", "typography", "density")

_SHA256_HEX = re.compile(r"^[0-9a-f]{64}$")


def _is_sha256(value) -> bool:
    return isinstance(value, str) and _SHA256_HEX.fullmatch(value) is not None

def _library_artifact_sha256() -> str | None:
    for item in ACTIVE_RUN.manifest.get("artifacts", []):
        if isinstance(item, dict) and item.get("id") == "library":
            digest = item.get("sha256")
            return digest if isinstance(digest, str) and digest else None
    return None

@lru_cache(maxsize=1)
def _computed_binding_roster() -> dict:
    """Canonical consuming elements and required contexts, independent of report input."""
    module = Path(__file__).resolve().with_name("companion-computed-cases.mjs").as_uri()
    result = subprocess.run(
        ["node", "--input-type=module", "-e",
         f"import {{BINDINGS}} from {json.dumps(module)}; console.log(JSON.stringify(BINDINGS));"],
        capture_output=True, text=True, check=True,
    )
    return {binding["id"]: binding for binding in json.loads(result.stdout)}


def _computed_rendered_case_ok(body: dict, case_id: str, component: str, dimension: str) -> bool:
    try:
        binding = _computed_binding_roster().get(case_id)
    except (OSError, ValueError, subprocess.SubprocessError):
        return False
    if binding is None or any(body.get(key) != binding.get(key) for key in
                              ("companion", "dimension", "element", "property", "token", "locate")):
        return False
    element, prop = body.get("element"), body.get("property")
    if not all(isinstance(v, str) and v for v in (element, prop)):
        return False
    if case_id != f"{component}/{dimension}/{element}/{prop}":
        return False
    token = body.get("token")
    prefixes = (f"--mat-{component}-", *_COMPUTED_FOREIGN_TOKEN_PREFIXES.get((component, dimension), ()))
    if not (isinstance(token, str) and token.startswith(prefixes)):
        return False
    keyword = body.get("peer_declared_keyword")
    if keyword is not None and keyword not in _CSS_WIDE_KEYWORDS:
        return False
    scenarios = body.get("scenarios")
    if not isinstance(scenarios, list) or not scenarios:
        return False
    if [row.get("scenario") if isinstance(row, dict) else None for row in scenarios] != binding["scenarios"]:
        return False
    seen = set()
    for scenario in scenarios:
        if not isinstance(scenario, dict) or scenario.get("match") is not True:
            return False
        name = scenario.get("scenario")
        if not isinstance(name, str) or not name or name in seen:
            return False
        seen.add(name)
        oracle = scenario.get("oracle")
        if not (isinstance(oracle, str) and oracle.strip() and scenario.get("candidate") == oracle and scenario.get("bridge") == oracle):
            return False
        # A token the peer declares with a CSS-wide keyword has no computed value of its own.
        if keyword is None and not (isinstance(scenario.get("oracle_token"), str) and scenario["oracle_token"].strip()):
            return False
    for key in ("negative", "bridge_negative"):
        negative = body.get(key)
        if not isinstance(negative, dict) or negative.get("scenario") != binding["negative_scenario"]:
            return False
        if negative.get("sentinel_consumed") is not True or negative.get("mismatch_detected") is not True:
            return False
        injected, observed = negative.get("injected"), negative.get("observed")
        if not (isinstance(injected, str) and injected and isinstance(observed, str) and observed):
            return False
        if observed == negative.get("oracle"):
            return False
    return True


def _computed_style_assertion_ok(body: dict, invocation: str) -> bool:
    """A companion computed-style assertion from this run's rendered peer oracle.

    Common: this run and invocation, the run's frozen @angular/material peer
    version and package.json digest, the run's library tarball, and the peer
    ``<companion>/_m2-<companion>.scss`` source. A rendered dimension case
    needs candidate == oracle (non-empty, peer token defined on the consuming
    element) in every scenario and a consumed wrong-but-nonempty negative. A
    not-applicable case needs the live peer dimension mixin to emit nothing.
    A peer-oracle case needs peer-only Sass and a sensitivity witness per
    applicable dimension.
    """
    case_id = body.get("case_id")
    component = body.get("companion")
    if not (isinstance(case_id, str) and case_id and isinstance(component, str) and component):
        return False
    if body.get("check_id") != "companion-computed-styles" or body.get("line") != "21.x":
        return False
    if body.get("run_id") != ACTIVE_RUN.manifest.get("run_id") or body.get("invocation_id") != invocation:
        return False
    if body.get("peer_package") != "@angular/material":
        return False
    peer_version = _current_peer_version("@angular/material")
    if peer_version is None or body.get("peer_version") != peer_version:
        return False
    if not _is_sha256(body.get("peer_package_json_sha256")):
        return False
    library = _library_artifact_sha256()
    if library is None or body.get("tarball_sha256") != library:
        return False
    source = body.get("peer_source_file")
    match = _PEER_SOURCE_FILE.fullmatch(source) if isinstance(source, str) else None
    if match is None or match.group(1) != component or not _is_sha256(body.get("peer_source_sha256")):
        return False
    if not (_is_sha256(body.get("oracle_css_sha256")) and _is_sha256(body.get("candidate_css_sha256"))):
        return False
    group = body.get("group")
    if group == "independent-peer-oracle":
        if case_id != f"{component}/peer-oracle":
            return False
        isolation = body.get("oracle_isolation")
        if not isinstance(isolation, dict) or isolation.get("peer_only") is not True:
            return False
        if isolation.get("legacy_package_loaded") is not False:
            return False
        applicable = body.get("applicable_dimensions")
        sensitivity = body.get("sensitivity")
        if not isinstance(applicable, list) or not applicable or not isinstance(sensitivity, dict):
            return False
        if set(sensitivity) != set(applicable):
            return False
        return all(isinstance(v, dict) and v.get("ok") is True for v in sensitivity.values())
    if group != "thirteen-companion-dimensions":
        return False
    dimension = body.get("dimension")
    if dimension not in _COMPUTED_DIMENSIONS:
        return False
    if body.get("not_applicable") is True:
        if case_id != f"{component}/{dimension}/not-applicable":
            return False
        if body.get("peer_mixin") != f"mat.{component}-{dimension}":
            return False
        return body.get("peer_emitted_tokens") == []
    return _computed_rendered_case_ok(body, case_id, component, dimension)

_M3_CASE_GROUPS = {
    "current-only": "inclusion-order",
    "legacy-only": "inclusion-order",
    "current-then-legacy": "inclusion-order",
    "legacy-then-current": "inclusion-order",
    "nested-theme-scope": "nested-lazy-overlay",
    "lazy-body-overlay": "nested-lazy-overlay",
    "current-shared-scope": "shared-style-boundary",
    "legacy-shared-scope": "shared-style-boundary",
}


def _m3_order_facts_ok(case_id: str, facts: dict) -> bool:
    m3, m2 = facts.get("m3_present"), facts.get("m2_present")
    if case_id == "current-only":
        return m3 is True and m2 is False
    if case_id == "legacy-only":
        return m2 is True and m3 is False
    i3, i2 = facts.get("m3_index"), facts.get("m2_index")
    if not (m3 is True and m2 is True and isinstance(i3, int) and isinstance(i2, int)):
        return False
    return i3 < i2 if case_id == "current-then-legacy" else i2 < i3


def _m3_rendered_check_ok(check) -> bool:
    if not isinstance(check, dict) or check.get("found") is not True or check.get("ok") is not True:
        return False
    if not all(isinstance(check.get(k), str) and check.get(k) for k in ("label", "probe", "observed", "reference")):
        return False
    props = check.get("properties")
    if not isinstance(props, list) or not props:
        return False
    for prop in props:
        if not isinstance(prop, dict) or not isinstance(prop.get("property"), str) or not prop.get("property"):
            return False
        if not all(isinstance(prop.get(k), str) and prop.get(k) for k in ("observed", "reference")):
            return False
    if check.get("expect") == "equal":
        return all(prop["observed"] == prop["reference"] for prop in props)
    if check.get("expect") == "differ":
        return any(prop["observed"] != prop["reference"] for prop in props)
    return False


def _m3_assertion_ok(body: dict, invocation: str) -> bool:
    """An m3-coexistence assertion from this run's packed library.

    It must name this run and invocation and the run's library tarball, carry
    a passing packed compile of its case, and a passing Chromium render of a
    fresh consumer install against the run's frozen @angular/material peer:
    every rendered check found its probes and holds on non-empty computed
    values. current-shared-scope also needs its contamination fixture
    detected and unrostered. A workspace compile is not accepted.
    """
    case_id = body.get("case_id")
    group = _M3_CASE_GROUPS.get(case_id) if isinstance(case_id, str) else None
    if group is None or body.get("group") != group:
        return False
    if body.get("check_id") != "m3-coexistence" or body.get("line") != "21.x":
        return False
    if body.get("result") != "pass" or body.get("kind") != "assertion" or body.get("source_kind") != "packed":
        return False
    if body.get("run_id") != ACTIVE_RUN.manifest.get("run_id") or body.get("invocation_id") != invocation:
        return False
    library = _library_artifact_sha256()
    if library is None or body.get("tarball_sha256") != library:
        return False
    peer_version = _current_peer_version("@angular/material")
    if peer_version is None or body.get("peer_version") != peer_version:
        return False
    facts = body.get("packed_compile")
    if not isinstance(facts, dict) or not facts:
        return False
    if group == "inclusion-order" and not _m3_order_facts_ok(case_id, facts):
        return False
    rendered = body.get("rendered")
    if not isinstance(rendered, dict) or rendered.get("result") != "pass":
        return False
    if not (isinstance(rendered.get("browser"), str) and rendered.get("browser")):
        return False
    versions = rendered.get("versions")
    if not isinstance(versions, dict) or versions.get("material") != peer_version:
        return False
    if not complete_rendered_checks(case_id, rendered):
        return False
    checks = rendered.get("checks")
    if not isinstance(checks, list) or not checks or not all(_m3_rendered_check_ok(c) for c in checks):
        return False
    if not any(c.get("expect") == "equal" for c in checks):
        return False
    if case_id == "current-shared-scope":
        negative = rendered.get("contamination_negative")
        if not isinstance(negative, dict) or negative.get("detected") is not True or negative.get("rostered") is not False:
            return False
    return True


def _consumer_floor_assertion_ok(body: dict, invocation: str) -> bool:
