def _sass_seal_assertion_ok(body: dict, invocation: str) -> bool:
    if body.get('case_id') in ORDINARY_CONTROL_GATE_CASES and str(body.get('case_id','')).startswith('mixin-css/'):
        return ordinary_control_gate_assertion_ok(ROOT,ACTIVE_RUN,body,invocation)
    if 'current_ordinary_controls' in body and body.get('case_id') not in ORDINARY_CONTROL_GATE_CASES:return False
    if body.get('case_id') in SPINNER_SNACK_GATE_CASES and str(body.get('case_id','')).startswith('mixin-css/'):
        return spinner_snack_gate_assertion_ok(ROOT,ACTIVE_RUN,body,invocation)
    if 'current_spinner_snack_bridge' in body and body.get('case_id') not in SPINNER_SNACK_GATE_CASES:return False
    if str(body.get('case_id', '')).startswith(('mixin-argument/', 'owned-aggregate/')):
        return mixin_argument_assertion_ok(ROOT, ACTIVE_RUN, body, invocation)
    if str(body.get('case_id', '')).startswith('function-value/'):
        return function_assertion_ok(ROOT, ACTIVE_RUN, body, invocation)
    if str(body.get('case_id', '')).startswith('owned-style/'):
        return owned_rendered_ok(ROOT, ACTIVE_RUN, body, invocation)
    if body.get('case_id') in RIPPLE_COLOR_DEFAULT_CASES:
        return ripple_color_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in RIPPLE_COLOR_ORDERED_CASES:
        return ripple_color_envelope_ok(ACTIVE_RUN,body,invocation,ordered=True)
    if body.get('case_id') in FORM_FIELD_STATE_DEFAULT_CASES:
        return form_field_state_default_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in DEFAULT_AGGREGATE_CASES:
        return default_aggregate_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in DEFAULT_MAPPED_COMPANION_CASES:
        return default_mapped_companion_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in DEFAULT_COMPANION_CASES:
        return default_companion_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in ORDERED_CORE_CASES:
        return 'current_companion' not in body and ordered_core_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in ORDERED_AGGREGATE_CASES:
        return ordered_aggregate_envelope_ok(ACTIVE_RUN,body,invocation)
    if body.get('case_id') in DEFAULT_CORE_CDK_CASES:
        return 'current_companion' not in body and default_core_cdk_envelope_ok(ACTIVE_RUN,body,invocation)
    if 'current_infrastructure' in body or 'current_companion' in body:return False
    return True


