def _complete_line_report(run_dir: Path, run_id: str, check_id: str) -> dict | None:
    """Coverage complete for the run's source line when that line's roster is resolved."""
    if ACTIVE_RUN is None or check_id not in _LINE_COORDINATOR_LIMITATIONS:
        return None
    line = ACTIVE_RUN.manifest.get("source", {}).get("line")
    if line not in ("main", "21.x"):
        return None
    matrix = read_json(MATRIX_PATH)
    row = validate_matrix(matrix)[check_id]
    groups = row["acceptance"]["cases_by_line"].get(line)
    if not isinstance(groups, dict) or any(ids is None for ids in groups.values()):
        return None
    expected = expected_cases(row, line)
    invocation = ACTIVE_RUN.invocation(check_id)
    records = _roster_assertion_records(run_dir, check_id, invocation, expected)
    artifacts = _contract_artifacts(row)
    if records is None or artifacts is None:
        return None
    outputs = []
    seen: set[str] = set()
    case_results = []
    for case_id in expected:
        record = records[case_id]
        if record["path"] not in seen:
            outputs.append(record)
            seen.add(record["path"])
        if check_id == "consumer-floors":
            body = read_json(run_dir / record["path"])
            for support in floor_support_records(body):
                if support["path"] not in seen:
                    outputs.append(support)
                    seen.add(support["path"])
        case_results.append({
            "case_id": case_id,
            "result": "pass",
            "kind": "assertion",
            "output_paths": [record["path"]],
        })
    spec = row["acceptance"]
    return {
        "schema_version": 1,
        "template": False,
        "run_id": run_id,
        "check_id": check_id,
        "line": line,
        "invocation_id": invocation,
        "binding": ACTIVE_RUN.binding,
        "coverage": "complete",
        "result": "pass",
        "exit_code": 0,
        "subject_kind": spec["subject_kind"],
        "subject_ids": list(spec["subject_ids"]),
        "artifacts": artifacts,
        "expected_case_ids": expected,
        "discovered_case_ids": list(expected),
        "executed_case_ids": list(expected),
        "passed_case_ids": list(expected),
        "failed_case_ids": [],
        "skipped_case_ids": [],
        "unresolved_case_ids": [],
        "exceptions": [],
        "passed": len(expected),
        "failed": 0,
        "skipped": 0,
        "outputs": outputs,
        "case_results": case_results,
        "command": ["rc-verify.py", check_id],
        "limitations": list(_LINE_COORDINATOR_LIMITATIONS[check_id]),
    }



def _migration_contract_artifacts(row: dict) -> dict | None:
    wanted = row["acceptance"]["subject_ids"]
    if wanted != ["library", "migrate-cli"]:
        return None
    by_id: dict = {}
    for item in ACTIVE_RUN.manifest.get("artifacts", []):
        aid = item.get("id")
        if aid not in wanted:
            continue
        if aid in by_id:
            return None
        digest = item.get("sha256")
        size = item.get("bytes")
        if not isinstance(digest, str) or type(size) is not int or size <= 0:
            return None
        by_id[aid] = {"sha256": digest, "bytes": size}
    if set(by_id) != set(wanted):
        return None
    return {aid: by_id[aid] for aid in wanted}

def _migration_assertion_records(run_dir: Path, invocation: str, expected: list[str]) -> dict | None:
    """Map rostered case ids to assertion files this run wrote.

    Copies of the manifest or other control files are not assertion evidence.
    """
    prefix = assertion_directory("migration-packaged", invocation)
    directory = run_dir / prefix
    if not directory.is_dir() or directory.is_symlink():
        return None
    reserved = _reserved_evidence(run_dir)
    allowed = set(expected)
    found: dict = {}
    for path in sorted(directory.iterdir()):
        if not path.is_file() or path.is_symlink() or path.stat().st_nlink != 1:
            continue
        if path.name in _MIGRATION_RESERVED_NAMES or path.suffix != ".json":
            continue
        if path.name.endswith((".sha256", ".sha512", ".sha1")):
            continue
        identity = (evidence_sha256(path), path.stat().st_size)
        if identity in reserved:
            continue
        try:
            body = read_json(path)
        except EvidenceError:
            continue
        case_id = body.get("case_id")
        if body.get("result") != "pass" or body.get("kind") != "assertion":
            continue
        if not isinstance(case_id, str) or case_id not in allowed or case_id in found:
            if isinstance(case_id, str) and case_id in found:
                return None
            continue
        if not old_workspace_assertion_ok(ROOT, ACTIVE_RUN, body, invocation) or not transaction_assertion_ok(ROOT, ACTIVE_RUN, body, invocation) or not frontend_assertion_ok(ROOT, ACTIVE_RUN, body, invocation):
            continue
        relative = path.relative_to(run_dir).as_posix()
        if not relative.startswith(prefix + "/"):
            continue
        found[case_id] = {"path": relative, "sha256": identity[0], "bytes": identity[1]}
    if set(found) != allowed:
        return None
    return found

def _complete_migration_report(run_dir: Path, run_id: str) -> dict | None:
    """Coverage complete only for 21.x, and only from the matrix roster.

    A 21.x run calls expected_cases for 21.x. Null main groups are not filled
    and are not passed to expected_cases.
    """
    if ACTIVE_RUN is None:
        return None
    matrix = read_json(MATRIX_PATH)
    row = validate_matrix(matrix)["migration-packaged"]
    groups = row["acceptance"]["cases_by_line"].get("21.x")
    if not isinstance(groups, dict) or any(ids is None for ids in groups.values()):
        return None
    expected = expected_cases(row, "21.x")
    invocation = ACTIVE_RUN.invocation("migration-packaged")
    records = _migration_assertion_records(run_dir, invocation, expected)
    artifacts = _migration_contract_artifacts(row)
    if records is None or artifacts is None:
        return None
    outputs = []
    seen: set[str] = set()
    case_results = []
    for case_id in expected:
        record = records[case_id]
        if record["path"] not in seen:
            outputs.append(record)
            seen.add(record["path"])
        body = read_json(run_dir / record["path"])
        for support in workspace_support_records(body):
            if support["path"] not in seen:
                outputs.append(support)
                seen.add(support["path"])
        case_results.append({
            "case_id": case_id,
            "result": "pass",
            "kind": "assertion",
            "output_paths": [record["path"]],
        })
    spec = row["acceptance"]
    return {
        "schema_version": 1,
        "template": False,
        "run_id": run_id,
        "check_id": "migration-packaged",
        "line": "21.x",
        "invocation_id": invocation,
        "binding": ACTIVE_RUN.binding,
        "coverage": "complete",
        "result": "pass",
        "exit_code": 0,
        "subject_kind": spec["subject_kind"],
        "subject_ids": list(spec["subject_ids"]),
        "artifacts": artifacts,
        "expected_case_ids": expected,
        "discovered_case_ids": list(expected),
        "executed_case_ids": list(expected),
        "passed_case_ids": list(expected),
        "failed_case_ids": [],
        "skipped_case_ids": [],
        "unresolved_case_ids": [],
        "exceptions": [],
        "passed": len(expected),
        "failed": 0,
        "skipped": 0,
        "outputs": outputs,
        "case_results": case_results,
        "command": ["rc-verify.py", "migration-packaged"],
        "limitations": [
            "Coordinator report for the line being verified. Each rostered 21.x case has an assertion file written by this run.",
            "Main migration groups stay null. A 21.x run does not copy them and does not call expected_cases for main.",
            "This report is the acceptance input. It does not add a G04 or G05 claim field.",
        ],
    }

def write_migration_packaged_report(
    run_dir: Path,
    run_id: str,
    line: str,
    *,
    exit_code: int,
    limitations: list[str] | None = None,
) -> None:
    """Write one migration-packaged report.

    Coverage is complete only when this main run's child exit is zero and every
    rostered 21.x case has a passing assertion file in the check-owned
    invocation directory. Any other outcome stays the incomplete slice.
    write_check_report must not replace a complete report.
    """
    report_path = run_dir / "reports" / "migration-packaged.json"
    complete = _complete_migration_report(run_dir, run_id) if exit_code == 0 and line == "21.x" else None
    if complete is None:
        write_check_report(
            run_dir, run_id, line, "migration-packaged",
            exit_code=exit_code, limitations=limitations,
        )
        return
    reports = report_path.parent
    reports.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(complete, indent=2) + "\n")
    before = report_path.read_bytes()
    write_check_report(
        run_dir, run_id, line, "migration-packaged",
        exit_code=exit_code, limitations=limitations,
    )
    if report_path.read_bytes() != before:
        raise EvidenceError("write_check_report overwrote a complete migration-packaged report")

def write_line_coordinator_report(
    run_dir: Path,
    run_id: str,
    line: str,
    check_id: str,
    *,
    exit_code: int,
    limitations: list[str] | None = None,
) -> None:
    """Complete when this run's line has a resolved roster and every assertion passes."""
    if check_id not in _LINE_COORDINATOR_LIMITATIONS:
        raise EvidenceError(f"no line coordinator report for {check_id}")
    report_path = run_dir / "reports" / f"{check_id}.json"
    complete = _complete_line_report(run_dir, run_id, check_id) if exit_code == 0 else None
    if complete is None:
        write_check_report(
            run_dir, run_id, line, check_id,
            exit_code=exit_code, limitations=limitations,
        )
        return
    reports = report_path.parent
    reports.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(complete, indent=2) + "\n")
    before = report_path.read_bytes()
    write_check_report(
        run_dir, run_id, line, check_id,
        exit_code=exit_code, limitations=limitations,
    )
    if report_path.read_bytes() != before:
        raise EvidenceError(f"write_check_report overwrote a complete {check_id} report")



